CREATE TABLE company_billing (company_id TEXT PRIMARY KEY REFERENCES company_registry(id),checkout_attempt TEXT,checkout_id TEXT,checkout_url TEXT,checkout_expires_at INTEGER NOT NULL DEFAULT 0,checkout_started_at INTEGER NOT NULL DEFAULT 0,customer_id TEXT,subscription_id TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'not_started',price_id TEXT,billing_interval TEXT,last_event_created INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE stripe_billing_events (id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES company_registry(id),created INTEGER NOT NULL,processed_at INTEGER NOT NULL);
